", "branch": "studio/give_finance_team_way-5c6f1ce7", "files": {"genie/give_finance_team_way_agent.json": "{
  "title": "Finance Margin & Cash Genie [dev 5c6f1ce7]",
  "space_id": "01f1e358daab117a807773963d806664",
  "url": "https://adb-7405604635797033.13.azuredatabricks.net/genie/rooms/01f1e358daab117a807773963d806664",
  "description": "Answers FP&A, category manager, and credit control questions about gross margin performance, discount drag, inventory ageing, DSO, and overdue receivables using governed metric views.",
  "data_sources": [
    "vmohan_demo_catalog.cfo_workbench.mv_inventory_ageing",
    "vmohan_demo_catalog.cfo_workbench.mv_revenue_margin",
    "vmohan_demo_catalog.cfo_workbench.mv_working_capital"
  ],
  "instructions": "This agent answers questions about gross margin vs plan, price realisation, inventory ageing, days sales outstanding, and overdue accounts receivable. Gross margin performance and gap to plan are measured by Gross Margin USD, Gross Margin Pct, Plan Gross Margin USD, Plan Gross Margin Pct, and GM vs Plan Bps from mv_revenue_margin; discount drag is measured by Price Realisation Pct and List Revenue from the same view. Inventory ageing is measured by Inventory Value, Inventory Over 180 Days, and Aged Share Pct from mv_inventory_ageing. DSO and past-due exposure are measured by DSO Days, Past Due Over 30 Days, and Collections Exposure Top 200 from mv_working_capital. When a question asks about 'latest' or 'this week', use the latest full week ending 2026-11-09 (Week Start = '2026-11-09') for views that carry a Week Start dimension. Results are company-wide unless a specific segment, branch, or category is requested. If a question references a target or threshold, the agent answers with the relevant measure and treats the target as analyst-supplied context. If no listed measure can address a question, the agent will say so clearly.",
  "sample_questions": [
    "Which categories and branches are below plan gross margin this week, and by how much?",
    "Where is price realisation falling \u2014 which categories or branches have the largest discount drag?",
    "How much inventory is aged over 180 days, and in which branches and categories?",
    "What is current DSO, and which customer segments are driving past-due exposure?",
    "Which top-200 accounts have open balances more than 30 days past due?"
  ],
  "benchmarks": [
    {
      "question": "What is current DSO, and which customer segments are driving past-due exposure?",
      "sql": "SELECT Segment, MEASURE(`DSO Days`), MEASURE(`Past Due Over 30 Days`), MEASURE(`Open AR`) FROM vmohan_demo_catalog.cfo_workbench.mv_working_capital GROUP BY ALL",
      "expected": "Retail: DSO Days: 50.0 days, Past Due Over 30 Days: $2.08M, Open AR: $41.00M; Government: DSO Days: 50.9 days, Past Due Over 30 Days: $810.5K, Open AR: $23.73M; Industrial: DSO Days: 51.7 days, Past Due Over 30 Days: $1.97M, Open AR: $43.43M; Trade: DSO Days: 42.1 days, Past Due Over 30 Days: $3.51M, Open AR: $70.98M"
    }
  ]
